```verilog
module axis_switch #
(
    parameter S_COUNT = 4,
    parameter M_COUNT = 4,
    parameter DATA_WIDTH = 8,
    parameter KEEP_ENABLE = (DATA_WIDTH>8),
    parameter KEEP_WIDTH = ((DATA_WIDTH+7)/8),
    parameter ID_ENABLE = 0,
    parameter S_ID_WIDTH = 8,
    parameter M_ID_WIDTH = S_ID_WIDTH+$clog2(S_COUNT),
    parameter M_DEST_WIDTH = 1,
    parameter S_DEST_WIDTH = M_DEST_WIDTH+$clog2(M_COUNT),
    parameter USER_ENABLE = 1,
    parameter USER_WIDTH = 1,
    parameter M_BASE = 0,
    parameter M_TOP = 0,
    parameter M_CONNECT = {M_COUNT{{S_COUNT{1'b1}}}},
    parameter UPDATE_TID = 0,
    parameter S_REG_TYPE = 0,
    parameter M_REG_TYPE = 2,
    parameter ARB_TYPE_ROUND_ROBIN = 1,
    parameter ARB_LSB_HIGH_PRIORITY = 1
)
(
    input  wire                             clk,
    input  wire                             rst,
    /*
     * AXI Stream inputs
     */
    input  wire [S_COUNT*DATA_WIDTH-1:0]    s_axis_tdata,
    input  wire [S_COUNT*KEEP_WIDTH-1:0]    s_axis_tkeep,
    input  wire [S_COUNT-1:0]               s_axis_tvalid,
    output wire [S_COUNT-1:0]               s_axis_tready,
    input  wire [S_COUNT-1:0]               s_axis_tlast,
    input  wire [S_COUNT*S_ID_WIDTH-1:0]    s_axis_tid,
    input  wire [S_COUNT*S_DEST_WIDTH-1:0]  s_axis_tdest,
    input  wire [S_COUNT*USER_WIDTH-1:0]    s_axis_tuser,
    /*
     * AXI Stream outputs
     */
    output wire [M_COUNT*DATA_WIDTH-1:0]    m_axis_tdata,
    output wire [M_COUNT*KEEP_WIDTH-1:0]    m_axis_tkeep,
    output wire [M_COUNT-1:0]               m_axis_tvalid,
    input  wire [M_COUNT-1:0]               m_axis_tready,
    output wire [M_COUNT-1:0]               m_axis_tlast,
    output wire [M_COUNT*M_ID_WIDTH-1:0]    m_axis_tid,
    output wire [M_COUNT*M_DEST_WIDTH-1:0]  m_axis_tdest,
    output wire [M_COUNT*USER_WIDTH-1:0]    m_axis_tuser
);

    // Internal parameters for logic sizing
    localparam LOG_S_COUNT = $clog2(S_COUNT);
    localparam LOG_M_COUNT = $clog2(M_COUNT);
    localparam LOG_KEEP_WIDTH = $clog2(KEEP_WIDTH);
    localparam LOG_USER_WIDTH = $clog2(USER_WIDTH);

    // State encoding for Round Robin Arbiter
    localparam [LOG_S_COUNT-1:0] STATE_IDLE = 0;
    localparam [LOG_S_COUNT-1:0] STATE_GRANT = 1;

    // Input Data Structures (Flattened to Vector)
    wire [S_COUNT*DATA_WIDTH-1:0] s_tdata;
    wire [S_COUNT*KEEP_WIDTH-1:0] s_tkeep;
    wire [S_COUNT-1:0]             s_tvalid;
    wire [S_COUNT-1:0]             s_tlast;
    wire [S_COUNT*S_ID_WIDTH-1:0]  s_tid;
    wire [S_COUNT*S_DEST_WIDTH-1:0] s_tdest;
    wire [S_COUNT*USER_WIDTH-1:0]  s_tuser;

    // Output Data Structures (Flattened to Vector)
    reg  [M_COUNT*DATA_WIDTH-1:0]  m_tdata;
    reg  [M_COUNT*KEEP_WIDTH-1:0]  m_tkeep;
    reg  [M_COUNT-1:0]             m_tvalid;
    reg  [M_COUNT-1:0]             m_tlast;
    reg  [M_COUNT*M_ID_WIDTH-1:0]  m_tid;
    reg  [M_COUNT*M_DEST_WIDTH-1:0] m_tdest;
    reg  [M_COUNT*USER_WIDTH-1:0]  m_tuser;

    // Internal Signals for Arbitration
    wire [S_COUNT-1:0] s_req;
    wire [S_COUNT-1:0] s_grant;
    wire [S_COUNT-1:0] s_ready;
    wire [S_COUNT-1:0] s_valid;
    wire [S_COUNT-1:0] s_last;
    wire [S_COUNT-1:0] s_dest;
    wire [S_COUNT-1:0] s_tid_idx;
    wire [S_COUNT-1:0] s_user_idx;

    // Internal Signals for Output
    wire [M_COUNT-1:0] m_valid;
    wire [M_COUNT-1:0] m_last;
    wire [M_COUNT-1:0] m_dest;
    wire [M_COUNT-1:0] m_tid_idx;
    wire [M_COUNT-1:0] m_user_idx;
    wire [M_COUNT-1:0] m_ready;

    // State Register for Round Robin
    reg [LOG_S_COUNT-1:0] rr_state;
    reg [LOG_S_COUNT-1:0] rr_next_state;
    reg [LOG_S_COUNT-1:0] rr_head;
    reg [LOG_S_COUNT-1:0] rr_next_head;
    reg [LOG_S_COUNT-1:0] rr_next_head_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next_next_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next_next_next_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next_next_next_next_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next_next_next_next_next_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next_next_next_next_next_next_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next_next_next_next_next_next_next_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next_next_next_next_next_next_next_next_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next_next_next_next_next_next_next_next_next_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next_next_next_next_next_next_next_next_next_next_next;
