    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next_next_next_next_next_next_next_next_next_next_next_next_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next_next_next_next_next_next_next_next_next_next_next_next_next_next;
    reg [LOG_S_COUNT-1:0] rr_next_head_next_next_next_next_next_next_next_next_next_next_next_next_next_next_next_next_next;
